//! Snippets: the Snippets tab list, inserting a snippet, and the Add Snippet window
//! (docs/UI_INVENTORY.md §4.4, §5.5).
//!
//! A snippet is a `<Name>.monosnippet` folder holding `snippet-metadata.json` and
//! `snippet-content.json` (a shape fragment). Standard snippets are generated by
//! `crates/core/examples/make_snippets.rs` and built into the binary; user snippets live in
//! `~/.local/share/solodraw/snippets`.

use crate::prelude::*;

macro_rules! standard {
    ($($name:literal),* $(,)?) => {
        &[$((
            $name,
            include_str!(concat!("../../../data/snippets/", $name, ".monosnippet/snippet-metadata.json")),
            include_str!(concat!("../../../data/snippets/", $name, ".monosnippet/snippet-content.json")),
        )),*]
    };
}

const STANDARD: &[(&str, &str, &str)] = standard!["Window (S)", "Window (M)", "Window (L)", "Dialog", "Browser", "Button", "Note"];

#[derive(Clone)]
pub struct Snippet {
    pub name: String,
    pub tags: String,
    pub description: String,
    pub user: bool,
    pub content: serde_json::Value,
}

fn parse(name: &str, meta: &str, content: &str, user: bool) -> Option<Snippet> {
    let m: serde_json::Value = serde_json::from_str(meta).unwrap_or_default();
    Some(Snippet {
        name: name.to_string(),
        tags: m["tags"].as_str().unwrap_or_default().to_string(),
        description: m["description"].as_str().unwrap_or_default().to_string(),
        user,
        content: serde_json::from_str(content).ok()?,
    })
}

pub fn user_dir() -> PathBuf {
    crate::actions::data_dir("snippets")
}

pub fn all() -> Vec<Snippet> {
    let mut v = Vec::new();
    if let Ok(dir) = std::fs::read_dir(user_dir()) {
        let mut dirs: Vec<PathBuf> = dir.flatten().map(|e| e.path()).filter(|p| p.extension().is_some_and(|e| e == "monosnippet")).collect();
        dirs.sort();
        for d in dirs {
            let name = d.file_stem().map(|n| n.to_string_lossy().to_string()).unwrap_or_default();
            let meta = std::fs::read_to_string(d.join("snippet-metadata.json")).unwrap_or_default();
            let Ok(content) = std::fs::read_to_string(d.join("snippet-content.json")) else { continue };
            v.extend(parse(&name, &meta, &content, true));
        }
    }
    v.extend(STANDARD.iter().filter_map(|(n, m, c)| parse(n, m, c, false)));
    v
}

/// The snippet rendered as text.
pub fn preview(sn: &Snippet) -> String {
    let (mut doc, canvas) = Document::new_empty();
    if doc.paste_fragment(&sn.content, &canvas, Point::default(), Point::default()).is_err() {
        return String::new();
    }
    let opts = TextOptions { anchor_origin: false, trim_padding: true, trim_trailing: true, unicode: None };
    canvas_to_text(&doc, Some(&canvas), &opts).unwrap_or_default()
}

/// Marks a snippet dragged from the Snippets tab; the rest of the string is its fragment JSON.
const DRAG_PREFIX: &str = "solodraw-snippet:";

/// Add a snippet's shapes centred in the visible canvas and select them.
pub fn insert(ui: &U, st: &St, sn: &Snippet) {
    let centre = crate::clipboard::visible_centre(ui, &st.borrow());
    insert_at(ui, st, &sn.content, centre);
}

/// Add a fragment's shapes centred on cell `centre` and select them.
fn insert_at(ui: &U, st: &St, content: &serde_json::Value, centre: Point) {
    {
        let mut s = st.borrow_mut();
        let (parent, t) = s.insert_parent();
        let mut doc = s.doc.clone();
        let Ok(roots) = doc.paste_fragment(content, &parent, t, Point::default()) else { return };
        let canvas = s.canvas.clone();
        let scene = solodraw_core::Scene::new(&doc, &canvas, true);
        let Some(f) = roots.iter().filter_map(|r| scene.frame(r)).reduce(|a, b| a.union(&b)) else { return };
        drop(scene);
        let d = Point::new(centre.x - f.w / 2 - f.x, centre.y - f.h / 2 - f.y);
        for r in &roots {
            doc.translate_shape(r, d);
        }
        s.checkpoint();
        s.doc = doc;
        s.selection = roots.into_iter().rev().collect();
        s.rerender();
    }
    sync(ui, st);
}

/// Canvas drop target for snippets dragged from the Snippets tab: they land centred on the
/// cell under the pointer. Other dropped text is refused.
pub fn canvas_drop_target(ui: &U, st: &St) -> gtk::DropTarget {
    let target = gtk::DropTarget::new(String::static_type(), gdk::DragAction::COPY);
    let (ui, st) = (ui.clone(), st.clone());
    target.connect_drop(move |_, v, x, y| {
        let Some(json) = v.get::<String>().ok().and_then(|p| p.strip_prefix(DRAG_PREFIX).map(str::to_string)) else { return false };
        let Ok(content) = serde_json::from_str(&json) else { return false };
        let centre = to_cell(&ui.area, &st.borrow(), x, y);
        insert_at(&ui, &st, &content, centre);
        true
    });
    target
}

thread_local! {
    /// Reload callbacks of every open Snippets tab (dropped when the tab is gone).
    static RELOADERS: RefCell<Vec<Box<dyn Fn() -> bool>>> = const { RefCell::new(Vec::new()) };
}

fn reload_all() {
    RELOADERS.with(|r| r.borrow_mut().retain(|f| f()));
}

pub struct SnippetsTab {
    pub page: gtk::Box,
    pub search: gtk::SearchEntry,
}

/// The Snippets tab: source filter, search, the list, and Add Snippet / Manage.
pub fn build_tab(ui_slot: &Rc<RefCell<Option<U>>>, st: &St) -> SnippetsTab {
    let page = gtk::Box::new(gtk::Orientation::Vertical, 6);
    page.set_margin_start(8);
    page.set_margin_end(8);
    page.set_margin_top(8);
    let which = gtk::DropDown::from_strings(&["All Snippets", "User Snippets", "Standard Snippets"]);
    which.set_selected(crate::prefs::get_int(crate::prefs::DEFAULT_SNIPPET_LIST, 0) as u32);
    page.append(&which);
    let search = gtk::SearchEntry::new();
    search.set_placeholder_text(Some("Search snippets"));
    page.append(&search);

    let list = gtk::ListBox::new();
    list.set_selection_mode(gtk::SelectionMode::None);
    list.add_css_class("md-snippets");
    let scroll = gtk::ScrolledWindow::new();
    scroll.set_child(Some(&list));
    scroll.set_vexpand(true);
    scroll.set_hscrollbar_policy(gtk::PolicyType::Never);
    page.append(&scroll);

    let brow = gtk::Box::new(gtk::Orientation::Horizontal, 8);
    brow.set_halign(gtk::Align::Center);
    brow.set_margin_bottom(8);
    let add = gtk::Button::with_label("Add Snippet");
    add.set_action_name(Some("win.add-snippet"));
    let manage = gtk::Button::with_label("Manage");
    manage.set_action_name(Some("win.reveal-snippets"));
    brow.append(&add);
    brow.append(&manage);
    page.append(&brow);

    let fill = {
        let (list, which, search, slot, st) = (list.downgrade(), which.downgrade(), search.downgrade(), ui_slot.clone(), st.clone());
        move || -> bool {
            let (Some(list), Some(which), Some(search)) = (list.upgrade(), which.upgrade(), search.upgrade()) else { return false };
            while let Some(c) = list.first_child() {
                list.remove(&c);
            }
            let q = search.text().to_lowercase();
            let mode = which.selected();
            let mut last_user: Option<bool> = None;
            for sn in all() {
                if (mode == 1 && !sn.user) || (mode == 2 && sn.user) {
                    continue;
                }
                if !q.is_empty() && !format!("{} {} {}", sn.name, sn.tags, sn.description).to_lowercase().contains(&q) {
                    continue;
                }
                if last_user != Some(sn.user) {
                    last_user = Some(sn.user);
                    let h = gtk::Label::new(Some(if sn.user { "User Snippets" } else { "Standard Snippets" }));
                    h.set_xalign(0.0);
                    h.add_css_class("md-section-title");
                    h.set_margin_top(6);
                    let row = gtk::ListBoxRow::new();
                    row.set_child(Some(&h));
                    row.set_activatable(false);
                    list.append(&row);
                }
                list.append(&snippet_row(&slot, &st, &sn));
            }
            if list.first_child().is_none() {
                let l = gtk::Label::new(Some(if q.is_empty() { "No snippets yet." } else { "No matching snippets." }));
                l.add_css_class("dim-label");
                l.set_margin_top(24);
                list.append(&l);
            }
            true
        }
    };
    fill();
    let fill = Rc::new(fill);
    {
        let f = fill.clone();
        which.connect_selected_notify(move |_| {
            f();
        });
    }
    {
        let f = fill.clone();
        search.connect_search_changed(move |_| {
            f();
        });
    }
    RELOADERS.with(|r| r.borrow_mut().push(Box::new(move || fill())));
    SnippetsTab { page, search }
}

fn snippet_row(slot: &Rc<RefCell<Option<U>>>, st: &St, sn: &Snippet) -> gtk::ListBoxRow {
    let row = gtk::ListBoxRow::new();
    row.set_activatable(false);
    let vb = gtk::Box::new(gtk::Orientation::Vertical, 2);
    vb.set_margin_top(4);
    vb.set_margin_bottom(4);
    let top = gtk::Box::new(gtk::Orientation::Horizontal, 4);
    let name = gtk::Label::new(Some(&sn.name));
    name.set_xalign(0.0);
    name.set_hexpand(true);
    name.set_ellipsize(pango::EllipsizeMode::End);
    top.append(&name);
    let plus = gtk::Button::from_icon_name("list-add-symbolic");
    plus.add_css_class("flat");
    plus.set_tooltip_text(Some("Add to canvas"));
    top.append(&plus);
    vb.append(&top);

    // Preview: small, runs of identical rows collapsed to two so tall shapes stay whole,
    // clipped to the pane width.
    let mut text: Vec<String> = Vec::new();
    for l in preview(sn).lines() {
        let l: String = l.chars().take(46).collect();
        if text.len() >= 2 && text[text.len() - 1] == l && text[text.len() - 2] == l {
            continue;
        }
        text.push(l);
    }
    text.truncate(14);
    let pv = gtk::Label::new(Some(&text.join("\n")));
    pv.set_xalign(0.0);
    pv.add_css_class("md-snippet-preview");
    vb.append(&pv);
    if !sn.description.is_empty() {
        row.set_tooltip_text(Some(&sn.description));
    }
    row.set_child(Some(&vb));

    let (slot2, st2, sn2) = (slot.clone(), st.clone(), sn.clone());
    plus.connect_clicked(move |_| {
        if let Some(ui) = slot2.borrow().clone() {
            insert(&ui, &st2, &sn2);
        }
    });
    // Double-click the preview also adds it.
    let click = gtk::GestureClick::new();
    let (slot3, st3, sn3) = (slot.clone(), st.clone(), sn.clone());
    click.connect_pressed(move |_, n, _, _| {
        if n == 2 {
            if let Some(ui) = slot3.borrow().clone() {
                insert(&ui, &st3, &sn3);
            }
        }
    });
    pv.add_controller(click);
    // Drag the row onto the canvas to add it there.
    let src = gtk::DragSource::new();
    src.set_actions(gdk::DragAction::COPY);
    let payload = format!("{DRAG_PREFIX}{}", sn.content);
    src.set_content(Some(&gdk::ContentProvider::for_value(&payload.to_value())));
    src.connect_drag_begin(move |src, _| src.set_icon(Some(&gtk::WidgetPaintable::new(Some(&pv))), 0, 0));
    row.add_controller(src);
    row
}

/// Folder-safe version of a snippet name.
fn file_name(name: &str) -> String {
    name.chars().map(|c| if matches!(c, '/' | '\\' | ':' | '\0') { '-' } else { c }).collect::<String>().trim().to_string()
}

/// The Add Snippet window: saves the selection as a user snippet.
pub fn add_snippet_dialog(ui: &U, st: &St) {
    let frag = {
        let s = st.borrow();
        let roots = s.selection_roots();
        if roots.is_empty() {
            drop(s);
            error(ui, "Select the shapes to save as a snippet first.");
            return;
        }
        s.doc.extract_fragment(&s.canvas, &roots)
    };
    let win = gtk::Window::builder().title("Add Snippet").transient_for(&ui.window).modal(true).resizable(false).build();
    let grid = gtk::Grid::new();
    grid.set_row_spacing(6);
    grid.set_column_spacing(8);
    grid.set_margin_start(16);
    grid.set_margin_end(16);
    grid.set_margin_top(16);
    grid.set_margin_bottom(12);
    let field = |row: i32, label: &str, hint: &str| {
        let l = gtk::Label::new(Some(label));
        l.set_xalign(1.0);
        grid.attach(&l, 0, row, 1, 1);
        let e = gtk::Entry::new();
        e.set_placeholder_text(Some(hint));
        e.set_width_chars(32);
        e.set_activates_default(true);
        grid.attach(&e, 1, row, 1, 1);
        e
    };
    let name = field(0, "Name:", "Required");
    let ident = field(1, "Identifier:", "Optional, reverse DNS notation");
    let tags = field(2, "Tags:", "Optional, space separated");
    let author = field(3, "Author:", "");
    let url = field(4, "Website:", "");
    let email = field(5, "Email:", "");
    let dl = gtk::Label::new(Some("Description:"));
    dl.set_xalign(1.0);
    dl.set_yalign(0.0);
    grid.attach(&dl, 0, 6, 1, 1);
    let desc = gtk::TextView::new();
    desc.set_wrap_mode(gtk::WrapMode::WordChar);
    let dscroll = gtk::ScrolledWindow::new();
    dscroll.set_child(Some(&desc));
    dscroll.set_min_content_height(64);
    dscroll.add_css_class("frame");
    grid.attach(&dscroll, 1, 6, 1, 1);

    let buttons = gtk::Box::new(gtk::Orientation::Horizontal, 8);
    buttons.set_halign(gtk::Align::End);
    buttons.set_margin_top(8);
    let cancel = gtk::Button::with_label("Cancel");
    let ok = gtk::Button::with_label("Add Snippet");
    ok.add_css_class("suggested-action");
    ok.set_sensitive(false);
    buttons.append(&cancel);
    buttons.append(&ok);
    grid.attach(&buttons, 0, 7, 2, 1);
    win.set_child(Some(&grid));
    win.set_default_widget(Some(&ok));

    {
        let ok = ok.clone();
        name.connect_changed(move |e| ok.set_sensitive(!file_name(&e.text()).is_empty()));
    }
    {
        let w = win.clone();
        cancel.connect_clicked(move |_| w.close());
    }
    let (w, ui2) = (win.clone(), ui.clone());
    ok.connect_clicked(move |_| {
        let n = file_name(&name.text());
        if n.is_empty() {
            return;
        }
        let buf = desc.buffer();
        let meta = json!({
            "author": author.text().as_str(),
            "email": email.text().as_str(),
            "version": 0,
            "description": buf.text(&buf.start_iter(), &buf.end_iter(), false).as_str(),
            "identifier": ident.text().as_str(),
            "tags": tags.text().as_str(),
            "url": url.text().as_str(),
        });
        let dir = user_dir().join(format!("{n}.monosnippet"));
        let r = std::fs::create_dir_all(&dir)
            .and_then(|_| std::fs::write(dir.join("snippet-metadata.json"), serde_json::to_vec_pretty(&meta).unwrap_or_default()))
            .and_then(|_| std::fs::write(dir.join("snippet-content.json"), serde_json::to_vec_pretty(&frag).unwrap_or_default()));
        match r {
            Ok(()) => {
                reload_all();
                ui2.status.set_text(&format!("Added snippet “{n}”"));
                w.close();
            }
            Err(e) => error(&ui2, &format!("Could not save the snippet in {}:\n{e}", dir.display())),
        }
    });
    win.present();
}
